// example.go
package main

import "fmt"

func main() {
	x := 42
	y := x + 8
	fmt.Println(y)
}

package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"golang.org/x/tools/go/packages"
	"log"
	"os"
	"path/filepath"
	"strings"
)

// TypeReference represents a reference to a type
type TypeReference struct {
	Name           string         `json:"name"`
	FullyQualified string         `json:"fullyQualified,omitempty"`
	Kind           string         `json:"kind"`
	IsPointer      bool           `json:"isPointer"`
	IsSlice        bool           `json:"isSlice"`
	IsMap          bool           `json:"isMap"`
	ElementType    *TypeReference `json:"elementType,omitempty"`
	KeyType        *TypeReference `json:"keyType,omitempty"`
	PackageName    string         `json:"packageName,omitempty"`
	ImportPath     string         `json:"importPath,omitempty"`
}

// Field represents a field in a struct
type Field struct {
	Name       string        `json:"name"`
	Type       TypeReference `json:"type"`
	IsExported bool          `json:"isExported"`
	IsEmbedded bool          `json:"isEmbedded"`
	Tags       string        `json:"tags,omitempty"`
	Doc        string        `json:"doc,omitempty"`
	LineStart  int           `json:"lineStart"`
	LineEnd    int           `json:"lineEnd"`
	SourceCode string        `json:"sourceCode,omitempty"`
}

// Parameter represents a function parameter
type Parameter struct {
	Name       string        `json:"name,omitempty"`
	Type       TypeReference `json:"type"`
	IsVariadic bool          `json:"isVariadic,omitempty"`
	LineStart  int           `json:"lineStart"`
	LineEnd    int           `json:"lineEnd"`
	SourceCode string        `json:"sourceCode,omitempty"`
}

// FunctionCall represents a function call
type FunctionCall struct {
	FunctionName string `json:"functionName"`
	PackageName  string `json:"packageName,omitempty"`
	ReceiverType string `json:"receiverType,omitempty"`
	LineStart    int    `json:"lineStart"`
	LineEnd      int    `json:"lineEnd"`
	Column       int    `json:"column"`
	SourceCode   string `json:"sourceCode,omitempty"`
}

// NestedFunction represents a function defined inside another function
type NestedFunction struct {
	ID            string                    `json:"id"`
	Name          string                    `json:"name"`
	Parameters    []Parameter               `json:"parameters"`
	ReturnTypes   []TypeReference           `json:"returnTypes"`
	Calls         []FunctionCall            `json:"calls,omitempty"`
	UsedTypes     []TypeReference           `json:"usedTypes,omitempty"`
	IsAnonymous   bool                      `json:"isAnonymous"`
	NestedFuncs   map[string]NestedFunction `json:"nestedFunctions,omitempty"`
	CapturedVars  []string                  `json:"capturedVariables,omitempty"`
	LineStart     int                       `json:"lineStart"`
	LineEnd       int                       `json:"lineEnd"`
	SourceCode    string                    `json:"sourceCode,omitempty"`
}

// Function represents a function or method declaration
type Function struct {
	ID            string                    `json:"id"`
	Name          string                    `json:"name"`
	PackageName   string                    `json:"packageName"`
	FilePath      string                    `json:"filePath"`
	IsExported    bool                      `json:"isExported"`
	IsMethod      bool                      `json:"isMethod"`
	ReceiverType  *TypeReference            `json:"receiverType,omitempty"`
	Parameters    []Parameter               `json:"parameters"`
	ReturnTypes   []TypeReference           `json:"returnTypes"`
	Calls         []FunctionCall            `json:"calls,omitempty"`
	UsedTypes     []TypeReference           `json:"usedTypes,omitempty"`
	NestedFuncs   map[string]NestedFunction `json:"nestedFunctions,omitempty"`
	HasClosures   bool                      `json:"hasClosures"`
	IsHigherOrder bool                      `json:"isHigherOrder"`
	LineStart     int                       `json:"lineStart"`
	LineEnd       int                       `json:"lineEnd"`
	Doc           string                    `json:"doc,omitempty"`
	SourceCode    string                    `json:"sourceCode,omitempty"`
}

// Type represents a type definition
type Type struct {
	ID           string         `json:"id"`
	Name         string         `json:"name"`
	PackageName  string         `json:"packageName"`
	FilePath     string         `json:"filePath"`
	Kind         string         `json:"kind"`
	Fields       []Field        `json:"fields,omitempty"`
	Methods      []string       `json:"methods,omitempty"`
	Implements   []string       `json:"implements,omitempty"`
	Underlying   *TypeReference `json:"underlying,omitempty"`
	IsExported   bool           `json:"isExported"`
	LineStart    int            `json:"lineStart"`
	LineEnd      int            `json:"lineEnd"`
	Doc          string         `json:"doc,omitempty"`
	SourceCode   string         `json:"sourceCode,omitempty"`
}

// Import represents an import statement
type Import struct {
	Path       string `json:"path"`
	Alias      string `json:"alias,omitempty"`
	IsDot      bool   `json:"isDot,omitempty"`
	FilePath   string `json:"filePath"`
	LineStart  int    `json:"lineStart"`
	LineEnd    int    `json:"lineEnd"`
	SourceCode string `json:"sourceCode,omitempty"`
}

// Package represents a Go package
type Package struct {
	ID        string              `json:"id"`
	Name      string              `json:"name"`
	Path      string              `json:"path"`
	Dir       string              `json:"dir,omitempty"`
	Imports   []Import            `json:"imports"`
	Types     map[string]Type     `json:"types"`
	Functions map[string]Function `json:"functions"`
	DependsOn []string            `json:"dependsOn"`
}

// ProjectGraph represents the entire project's dependency graph
type ProjectGraph struct {
	Name     string             `json:"name"`
	Packages map[string]Package `json:"packages"`
}

// SourceCodeCache holds file contents to avoid repeated file reading
type SourceCodeCache struct {
	files map[string][]string // filename -> lines of code
}

// NewSourceCodeCache creates a new source code cache
func NewSourceCodeCache() *SourceCodeCache {
	return &SourceCodeCache{
		files: make(map[string][]string),
	}
}

// GetSourceCode gets source code snippet from file
func (c *SourceCodeCache) GetSourceCode(filename string, start, end int) string {
	if _, ok := c.files[filename]; !ok {
		data, err := os.ReadFile(filename)
		if err != nil {
			log.Printf("Error reading file %s: %v", filename, err)
			return ""
		}
		c.files[filename] = strings.Split(string(data), "\n")
	}

	lines := c.files[filename]
	if start <= 0 || start > len(lines) {
		return ""
	}

	if end > len(lines) {
		end = len(lines)
	}

	// Adjust for 0-based lines array
	codeLines := lines[start-1:end]
	return strings.Join(codeLines, "\n")
}

func main() {
	// Parse command line arguments
	directory := flag.String("dir", ".", "Path to a directory to analyze")
	outputFile := flag.String("output", "dependency-graph.json", "Output JSON file path")
	verbose := flag.Bool("verbose", false, "Enable verbose logging")
	flag.Parse()

	// Create a new project graph
	projectGraph := ProjectGraph{
		Name:     filepath.Base(*directory),
		Packages: make(map[string]Package),
	}

	// Create source code cache
	sourceCache := NewSourceCodeCache()

	// Configure the package loader
	cfg := &packages.Config{
		Mode: packages.NeedName |
			packages.NeedFiles |
			packages.NeedImports |
			packages.NeedDeps |
			packages.NeedTypes |
			packages.NeedSyntax |
			packages.NeedTypesInfo,
		Dir:   *directory,
		Tests: false,
	}

	// Load packages
	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		log.Fatalf("Failed to load packages: %v", err)
	}

	if *verbose {
		log.Printf("Found %d packages", len(pkgs))
	}

	// Process each package
	for _, pkg := range pkgs {
		// Skip packages with errors
		if len(pkg.Errors) > 0 {
			log.Printf("Skipping package %s due to errors: %v", pkg.PkgPath, pkg.Errors)
			continue
		}

		// Create package structure
		packageInfo := Package{
			ID:        pkg.PkgPath,
			Name:      pkg.Name,
			Path:      pkg.PkgPath,
			Dir:       pkg.PkgPath,
			Imports:   []Import{},
			Types:     make(map[string]Type),
			Functions: make(map[string]Function),
			DependsOn: []string{},
		}

		// Process imports, types and functions for each file
		for _, file := range pkg.Syntax {
			filePath := pkg.Fset.Position(file.Pos()).Filename

			if *verbose {
				log.Printf("Processing file: %s", filePath)
			}

			processImports(file, pkg.Fset, filePath, sourceCache, &packageInfo)
			processTypes(file, pkg.Fset, pkg.TypesInfo, pkg.PkgPath, filePath, sourceCache, &packageInfo)
			processFunctions(file, pkg.Fset, pkg.TypesInfo, pkg.PkgPath, filePath, sourceCache, &packageInfo)
		}

		// Add to project graph
		projectGraph.Packages[pkg.PkgPath] = packageInfo
	}

	// Write output to JSON file
	jsonData, err := json.MarshalIndent(projectGraph, "", "  ")
	if err != nil {
		log.Fatalf("Error marshaling JSON: %v", err)
	}

	err = os.WriteFile(*outputFile, jsonData, 0644)
	if err != nil {
		log.Fatalf("Error writing output file: %v", err)
	}

	fmt.Printf("Dependency graph written to %s\n", *outputFile)
}

func processImports(file *ast.File, fset *token.FileSet, filePath string, sourceCache *SourceCodeCache, pkg *Package) {
	for _, imp := range file.Imports {
		path := strings.Trim(imp.Path.Value, "\"")
		startPos := fset.Position(imp.Pos())
		endPos := fset.Position(imp.End())

		importInfo := Import{
			Path:      path,
			FilePath:  filePath,
			LineStart: startPos.Line,
			LineEnd:   endPos.Line,
			SourceCode: sourceCache.GetSourceCode(filePath, startPos.Line, endPos.Line),
		}

		if imp.Name != nil {
			if imp.Name.Name == "." {
				importInfo.IsDot = true
			} else {
				importInfo.Alias = imp.Name.Name
			}
		}

		pkg.Imports = append(pkg.Imports, importInfo)
		pkg.DependsOn = append(pkg.DependsOn, path)
	}
}

func processTypes(file *ast.File, fset *token.FileSet, info *types.Info, packagePath string, filePath string, sourceCache *SourceCodeCache, pkg *Package) {
	for _, decl := range file.Decls {
		genDecl, ok := decl.(*ast.GenDecl)
		if !ok || genDecl.Tok != token.TYPE {
			continue
		}

		for _, spec := range genDecl.Specs {
			typeSpec, ok := spec.(*ast.TypeSpec)
			if !ok {
				continue
			}

			typeName := typeSpec.Name.Name
			isExported := ast.IsExported(typeName)
			startPos := fset.Position(typeSpec.Pos())
			endPos := fset.Position(typeSpec.End())

			typeID := fmt.Sprintf("%s.%s", packagePath, typeName)
			typeKind := determineTypeKind(typeSpec.Type)

			typeInfo := Type{
				ID:          typeID,
				Name:        typeName,
				PackageName: packagePath,
				FilePath:    filePath,
				Kind:        typeKind,
				IsExported:  isExported,
				LineStart:   startPos.Line,
				LineEnd:     endPos.Line,
				SourceCode:  sourceCache.GetSourceCode(filePath, startPos.Line, endPos.Line),
			}

			// Add documentation if available
			if genDecl.Doc != nil {
				typeInfo.Doc = genDecl.Doc.Text()
			} else if typeSpec.Doc != nil {
				typeInfo.Doc = typeSpec.Doc.Text()
			}

			// Process struct fields
			if structType, ok := typeSpec.Type.(*ast.StructType); ok {
				typeInfo.Fields = processStructFields(structType, info, fset, filePath, sourceCache)
			}

			// Process interface methods
			if interfaceType, ok := typeSpec.Type.(*ast.InterfaceType); ok {
				typeInfo.Methods = processInterfaceMethods(interfaceType)
			}

			// Process underlying types for type aliases
			if ident, ok := typeSpec.Type.(*ast.Ident); ok {
				typeRef := typeReferenceFromExpr(ident, info)
				typeInfo.Underlying = &typeRef
			}

			// Add the type to our package
			pkg.Types[typeID] = typeInfo
		}
	}
}

func determineTypeKind(expr ast.Expr) string {
	switch expr.(type) {
	case *ast.StructType:
		return "struct"
	case *ast.InterfaceType:
		return "interface"
	case *ast.ArrayType:
		return "array"
	case *ast.MapType:
		return "map"
	case *ast.ChanType:
		return "channel"
	case *ast.FuncType:
		return "func"
	case *ast.Ident:
		return "alias"
	case *ast.SelectorExpr:
		return "alias"
	default:
		return fmt.Sprintf("%T", expr)
	}
}

func processStructFields(structType *ast.StructType, info *types.Info, fset *token.FileSet, filePath string, sourceCache *SourceCodeCache) []Field {
	var fields []Field

	if structType.Fields == nil {
		return fields
	}

	for _, field := range structType.Fields.List {
		typeRef := typeReferenceFromExpr(field.Type, info)
		isEmbedded := len(field.Names) == 0
		startPos := fset.Position(field.Pos())
		endPos := fset.Position(field.End())

		// For embedded fields
		if isEmbedded {
			fields = append(fields, Field{
				Type:       typeRef,
				IsEmbedded: true,
				IsExported: true,
				Tags:       getFieldTags(field),
				LineStart:  startPos.Line,
				LineEnd:    endPos.Line,
				SourceCode: sourceCache.GetSourceCode(filePath, startPos.Line, endPos.Line),
			})
		} else {
			// For regular fields
			for _, name := range field.Names {
				fields = append(fields, Field{
					Name:       name.Name,
					Type:       typeRef,
					IsExported: ast.IsExported(name.Name),
					IsEmbedded: false,
					Tags:       getFieldTags(field),
					LineStart:  startPos.Line,
					LineEnd:    endPos.Line,
					SourceCode: sourceCache.GetSourceCode(filePath, startPos.Line, endPos.Line),
				})
			}
		}

		// Add documentation if available
		if field.Doc != nil {
			for i := range fields {
				if fields[i].LineStart == startPos.Line {
					fields[i].Doc = field.Doc.Text()
				}
			}
		}
	}

	return fields
}

func getFieldTags(field *ast.Field) string {
	if field.Tag != nil {
		return strings.Trim(field.Tag.Value, "`")
	}
	return ""
}

func processInterfaceMethods(interfaceType *ast.InterfaceType) []string {
	var methods []string

	if interfaceType.Methods == nil {
		return methods
	}

	for _, method := range interfaceType.Methods.List {
		if len(method.Names) > 0 {
			// It's a method
			methodName := method.Names[0].Name
			methods = append(methods, methodName)
		} else {
			// It's an embedded interface
			switch typeExpr := method.Type.(type) {
			case *ast.Ident:
				methods = append(methods, typeExpr.Name) // Embedded interface from same package
			case *ast.SelectorExpr:
				if x, ok := typeExpr.X.(*ast.Ident); ok {
					methods = append(methods, fmt.Sprintf("%s.%s", x.Name, typeExpr.Sel.Name))
				}
			}
		}
	}

	return methods
}

func processFunctions(file *ast.File, fset *token.FileSet, info *types.Info, packagePath string, filePath string, sourceCache *SourceCodeCache, pkg *Package) {
	for _, decl := range file.Decls {
		funcDecl, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}

		// Process the function
		funcName := funcDecl.Name.Name
		isExported := ast.IsExported(funcName)
		startPos := fset.Position(funcDecl.Pos())
		endPos := fset.Position(funcDecl.End())

		function := Function{
			Name:        funcName,
			PackageName: packagePath,
			FilePath:    filePath,
			IsExported:  isExported,
			IsMethod:    funcDecl.Recv != nil,
			Parameters:  []Parameter{},
			ReturnTypes: []TypeReference{},
			Calls:       []FunctionCall{},
			UsedTypes:   []TypeReference{},
			NestedFuncs: make(map[string]NestedFunction),
			LineStart:   startPos.Line,
			LineEnd:     endPos.Line,
			SourceCode:  sourceCache.GetSourceCode(filePath, startPos.Line, endPos.Line),
		}

		// Add documentation if available
		if funcDecl.Doc != nil {
			function.Doc = funcDecl.Doc.Text()
		}

		// Generate function ID
		if function.IsMethod && funcDecl.Recv != nil && len(funcDecl.Recv.List) > 0 {
			recvField := funcDecl.Recv.List[0]
			recvType := typeReferenceFromExpr(recvField.Type, info)
			function.ReceiverType = &recvType

			// Strip pointer from receiver type name for ID
			recvTypeName := recvType.Name
			if recvType.IsPointer && recvType.ElementType != nil {
				recvTypeName = recvType.ElementType.Name
			}

			function.ID = fmt.Sprintf("%s.%s.%s", packagePath, recvTypeName, funcName)
		} else {
			function.ID = fmt.Sprintf("%s.%s", packagePath, funcName)
		}

		// Process parameters
		if funcDecl.Type.Params != nil {
			processParameters(funcDecl.Type.Params, info, fset, filePath, sourceCache, &function)
		}

		// Process return types
		if funcDecl.Type.Results != nil {
			processReturnTypes(funcDecl.Type.Results, info, &function)
		}

		// Process function body
		if funcDecl.Body != nil {
			nestedFuncCount := 0
			typeUses := make(map[string]TypeReference)

			// Find function calls, type references, and nested functions
			ast.Inspect(funcDecl.Body, func(n ast.Node) bool {
				if n == nil {
					return true
				}

				// Find function calls
				if callExpr, ok := n.(*ast.CallExpr); ok {
					call := extractFunctionCall(callExpr, info, fset, filePath, sourceCache)
					if call != nil {
						function.Calls = append(function.Calls, *call)
					}
				}

				// Find type references
				if expr, ok := n.(ast.Expr); ok {
					if tv, ok := info.Types[expr]; ok && tv.Type != nil {
						typeRef := typeReferenceFromTypeAndValue(tv, expr, info)
						key := typeRef.FullyQualified
						if key == "" {
							key = typeRef.Name
						}
						typeUses[key] = typeRef
					}
				}

				// Find anonymous functions and closures
				if funcLit, ok := n.(*ast.FuncLit); ok {
					function.HasClosures = true
					nestedFunc := processNestedFunction(funcLit, info, fset, function.ID, &nestedFuncCount, filePath, sourceCache)
					function.NestedFuncs[nestedFunc.ID] = nestedFunc
				}

				return true
			})

			// Convert map of type uses to slice
			for _, typeRef := range typeUses {
				function.UsedTypes = append(function.UsedTypes, typeRef)
			}
		}

		// Determine if it's a higher-order function
		function.IsHigherOrder = isHigherOrderFunction(function.Parameters, function.ReturnTypes)

		// Add function to package
		pkg.Functions[function.ID] = function
	}
}

func processParameters(fieldList *ast.FieldList, info *types.Info, fset *token.FileSet, filePath string, sourceCache *SourceCodeCache, function *Function) {
	for _, field := range fieldList.List {
		typeRef := typeReferenceFromExpr(field.Type, info)
		isVariadic := false
		startPos := fset.Position(field.Pos())
		endPos := fset.Position(field.End())

		// Check if this is a variadic parameter
		if _, ok := field.Type.(*ast.Ellipsis); ok {
			isVariadic = true
		}

		if len(field.Names) == 0 {
			// Unnamed parameter
			function.Parameters = append(function.Parameters, Parameter{
				Type:       typeRef,
				IsVariadic: isVariadic,
				LineStart:  startPos.Line,
				LineEnd:    endPos.Line,
				SourceCode: sourceCache.GetSourceCode(filePath, startPos.Line, endPos.Line),
			})
		} else {
			// Named parameters
			for _, name := range field.Names {
				function.Parameters = append(function.Parameters, Parameter{
					Name:       name.Name,
					Type:       typeRef,
					IsVariadic: isVariadic,
					LineStart:  startPos.Line,
					LineEnd:    endPos.Line,
					SourceCode: sourceCache.GetSourceCode(filePath, startPos.Line, endPos.Line),
				})
			}
		}
	}
}

func processReturnTypes(fieldList *ast.FieldList, info *types.Info, function *Function) {
	for _, field := range fieldList.List {
		typeRef := typeReferenceFromExpr(field.Type, info)

		if len(field.Names) == 0 {
			// Unnamed result
			function.ReturnTypes = append(function.ReturnTypes, typeRef)
		} else {
			// Named results
			for _ = range field.Names {
				function.ReturnTypes = append(function.ReturnTypes, typeRef)
			}
		}
	}
}

func processNestedFunction(funcLit *ast.FuncLit, info *types.Info, fset *token.FileSet, parentID string, counter *int, filePath string, sourceCache *SourceCodeCache) NestedFunction {
	*counter++
	funcName := fmt.Sprintf("anonymous_%d", *counter)
	funcID := fmt.Sprintf("%s$%s", parentID, funcName)

	startPos := fset.Position(funcLit.Pos())
	endPos := fset.Position(funcLit.End())

	nestedFunc := NestedFunction{
		ID:          funcID,
		Name:        funcName,
		Parameters:  []Parameter{},
		ReturnTypes: []TypeReference{},
		Calls:       []FunctionCall{},
		UsedTypes:   []TypeReference{},
		IsAnonymous: true,
		NestedFuncs: make(map[string]NestedFunction),
		LineStart:   startPos.Line,
		LineEnd:     endPos.Line,
		SourceCode:  sourceCache.GetSourceCode(filePath, startPos.Line, endPos.Line),
	}

	// Process parameters
	if funcLit.Type.Params != nil {
		for _, field := range funcLit.Type.Params.List {
			typeRef := typeReferenceFromExpr(field.Type, info)
			isVariadic := false
			paramStartPos := fset.Position(field.Pos())
			paramEndPos := fset.Position(field.End())

			// Check if this is a variadic parameter
			if _, ok := field.Type.(*ast.Ellipsis); ok {
				isVariadic = true
			}

			if len(field.Names) == 0 {
				// Unnamed parameter
				nestedFunc.Parameters = append(nestedFunc.Parameters, Parameter{
					Type:       typeRef,
					IsVariadic: isVariadic,
					LineStart:  paramStartPos.Line,
					LineEnd:    paramEndPos.Line,
					SourceCode: sourceCache.GetSourceCode(filePath, paramStartPos.Line, paramEndPos.Line),
				})
			} else {
				// Named parameters
				for _, name := range field.Names {
					nestedFunc.Parameters = append(nestedFunc.Parameters, Parameter{
						Name:       name.Name,
						Type:       typeRef,
						IsVariadic: isVariadic,
						LineStart:  paramStartPos.Line,
						LineEnd:    paramEndPos.Line,
						SourceCode: sourceCache.GetSourceCode(filePath, paramStartPos.Line, paramEndPos.Line),
					})
				}
			}
		}
	}

	// Process return types
	if funcLit.Type.Results != nil {
		for _, field := range funcLit.Type.Results.List {
			typeRef := typeReferenceFromExpr(field.Type, info)

			if len(field.Names) == 0 {
				// Unnamed result
				nestedFunc.ReturnTypes = append(nestedFunc.ReturnTypes, typeRef)
			} else {
				// Named results
				for _ = range field.Names {
					nestedFunc.ReturnTypes = append(nestedFunc.ReturnTypes, typeRef)
				}
			}
		}
	}

	// Process function body
	if funcLit.Body != nil {
		nestedFuncCount := 0
		typeUses := make(map[string]TypeReference)

		// Find function calls, type references, and nested functions
		ast.Inspect(funcLit.Body, func(n ast.Node) bool {
			if n == nil {
				return true
			}

			// Find function calls
			if callExpr, ok := n.(*ast.CallExpr); ok {
				call := extractFunctionCall(callExpr, info, fset, filePath, sourceCache)
				if call != nil {
					nestedFunc.Calls = append(nestedFunc.Calls, *call)
				}
			}

			// Find type references
			if expr, ok := n.(ast.Expr); ok {
				if tv, ok := info.Types[expr]; ok && tv.Type != nil {
					typeRef := typeReferenceFromTypeAndValue(tv, expr, info)
					key := typeRef.FullyQualified
					if key == "" {
						key = typeRef.Name
					}
					typeUses[key] = typeRef
				}
			}

			// Find further nested functions
			if innerFuncLit, ok := n.(*ast.FuncLit); ok {
				innerFunc := processNestedFunction(innerFuncLit, info, fset, funcID, &nestedFuncCount, filePath, sourceCache)
				nestedFunc.NestedFuncs[innerFunc.ID] = innerFunc
			}

			return true
		})

		// Convert map of type uses to slice
		for _, typeRef := range typeUses {
			nestedFunc.UsedTypes = append(nestedFunc.UsedTypes, typeRef)
		}

		// Find captured variables (simplified approach)
		ast.Inspect(funcLit.Body, func(n ast.Node) bool {
			if n == nil {
				return true
			}

			if ident, ok := n.(*ast.Ident); ok {
				if obj := info.Uses[ident]; obj != nil {
					// Check if it's a reference to a variable from outer scope
					if _, ok := obj.(*types.Var); ok {
						scope := info.Scopes[funcLit]
						if scope != nil && !inScope(obj, scope) {
							nestedFunc.CapturedVars = appendUnique(nestedFunc.CapturedVars, ident.Name)
						}
					}
				}
			}

			return true
		})
	}

	return nestedFunc
}

func inScope(obj types.Object, scope *types.Scope) bool {
	if scope.Lookup(obj.Name()) == obj {
		return true
	}

	if scope.Parent() == nil {
		return false
	}

	return inScope(obj, scope.Parent())
}

func appendUnique(slice []string, item string) []string {
	for _, s := range slice {
		if s == item {
			return slice
		}
	}
	return append(slice, item)
}

func extractFunctionCall(callExpr *ast.CallExpr, info *types.Info, fset *token.FileSet, filePath string, sourceCache *SourceCodeCache) *FunctionCall {
	var packageName, functionName, receiverType string

	switch fun := callExpr.Fun.(type) {
	case *ast.Ident:
		// Local function call: myFunc()
		functionName = fun.Name
		// Try to get package info from type checking
		if obj := info.Uses[fun]; obj != nil {
			if pkg := obj.Pkg(); pkg != nil {
				packageName = pkg.Name()
			}
		}
	case *ast.SelectorExpr:
		// Either package.Function() or value.Method()
		functionName = fun.Sel.Name

		// Try to determine if this is a method call or package function
		if sel, ok := info.Selections[fun]; ok {
			// It's a method call
			receiverType = sel.Recv().String()
			// Strip package path if present
			if idx := strings.LastIndex(receiverType, "."); idx >= 0 {
				receiverType = receiverType[idx+1:]
			}
			// Strip pointer star if present
			receiverType = strings.TrimPrefix(receiverType, "*")
		} else {
			// Likely a package.Function call
			if x, ok := fun.X.(*ast.Ident); ok {
				packageName = x.Name
			}
		}
	default:
		// Complex expression or function literal call
		return nil
	}

	// If we couldn't determine a function name, skip it
	if functionName == "" {
		return nil
	}

	startPos := fset.Position(callExpr.Pos())
	endPos := fset.Position(callExpr.End())

	return &FunctionCall{
		FunctionName: functionName,
		PackageName:  packageName,
		ReceiverType: receiverType,
		LineStart:    startPos.Line,
		LineEnd:      endPos.Line,
		Column:       startPos.Column,
		SourceCode:   sourceCache.GetSourceCode(filePath, startPos.Line, endPos.Line),
	}
}

func typeReferenceFromExpr(expr ast.Expr, info *types.Info) TypeReference {
	// Try to get type information from info
	if tv, ok := info.Types[expr]; ok {
		return typeReferenceFromTypeAndValue(tv, expr, info)
	}

	// Fallback to syntax-based type extraction
	return typeReferenceFromSyntax(expr)
}

func typeReferenceFromTypeAndValue(tv types.TypeAndValue, expr ast.Expr, info *types.Info) TypeReference {
	if tv.Type == nil {
		return typeReferenceFromSyntax(expr)
	}

	typeRef := TypeReference{
		Name:      tv.Type.String(),
		Kind:      typeKindFromTypes(tv.Type),
		IsPointer: false,
		IsSlice:   false,
		IsMap:     false,
	}

	// Get fully qualified name if possible
	if named, ok := tv.Type.(*types.Named); ok {
		obj := named.Obj()
		if obj != nil {
			if pkg := obj.Pkg(); pkg != nil {
				typeRef.PackageName = pkg.Name()
				typeRef.ImportPath = pkg.Path()
				typeRef.FullyQualified = fmt.Sprintf("%s.%s", pkg.Name(), obj.Name())
			}
			typeRef.Name = obj.Name()
		}
	}

	// Handle pointers
	if ptr, ok := tv.Type.(*types.Pointer); ok {
		typeRef.IsPointer = true
		elemType := typeReferenceFromTypesType(ptr.Elem())
		typeRef.ElementType = &elemType
		typeRef.Name = "*" + elemType.Name
	}

	// Handle slices
	if slice, ok := tv.Type.(*types.Slice); ok {
		typeRef.IsSlice = true
		elemType := typeReferenceFromTypesType(slice.Elem())
		typeRef.ElementType = &elemType
		typeRef.Name = "[]" + elemType.Name
	}

	// Handle maps
	if mapType, ok := tv.Type.(*types.Map); ok {
		typeRef.IsMap = true
		keyType := typeReferenceFromTypesType(mapType.Key())
		elemType := typeReferenceFromTypesType(mapType.Elem())
		typeRef.KeyType = &keyType
		typeRef.ElementType = &elemType
		typeRef.Name = fmt.Sprintf("map[%s]%s", keyType.Name, elemType.Name)
	}

	return typeRef
}

func typeReferenceFromTypesType(t types.Type) TypeReference {
	typeRef := TypeReference{
		Name:      t.String(),
		Kind:      typeKindFromTypes(t),
		IsPointer: false,
		IsSlice:   false,
		IsMap:     false,
	}

	// Get fully qualified name if it's a named type
	if named, ok := t.(*types.Named); ok {
		obj := named.Obj()
		if obj != nil {
			if pkg := obj.Pkg(); pkg != nil {
				typeRef.PackageName = pkg.Name()
				typeRef.ImportPath = pkg.Path()
				typeRef.FullyQualified = fmt.Sprintf("%s.%s", pkg.Name(), obj.Name())
			}
			typeRef.Name = obj.Name()
		}
	}

	// Handle pointers
	if ptr, ok := t.(*types.Pointer); ok {
		typeRef.IsPointer = true
		elemType := typeReferenceFromTypesType(ptr.Elem())
		typeRef.ElementType = &elemType
		typeRef.Name = "*" + elemType.Name
	}

	// Handle slices
	if slice, ok := t.(*types.Slice); ok {
		typeRef.IsSlice = true
		elemType := typeReferenceFromTypesType(slice.Elem())
		typeRef.ElementType = &elemType
		typeRef.Name = "[]" + elemType.Name
	}

	// Handle maps
	if mapType, ok := t.(*types.Map); ok {
		typeRef.IsMap = true
		keyType := typeReferenceFromTypesType(mapType.Key())
		elemType := typeReferenceFromTypesType(mapType.Elem())
		typeRef.KeyType = &keyType
		typeRef.ElementType = &elemType
		typeRef.Name = fmt.Sprintf("map[%s]%s", keyType.Name, elemType.Name)
	}

	return typeRef
}

func typeKindFromTypes(t types.Type) string {
	switch t := t.(type) {
	case *types.Basic:
		return "basic"
	case *types.Named:
		if _, ok := t.Underlying().(*types.Struct); ok {
			return "struct"
		}
		if _, ok := t.Underlying().(*types.Interface); ok {
			return "interface"
		}
		return "named"
	case *types.Struct:
		return "struct"
	case *types.Interface:
		return "interface"
	case *types.Pointer:
		return "pointer"
	case *types.Slice:
		return "slice"
	case *types.Array:
		return "array"
	case *types.Map:
		return "map"
	case *types.Chan:
		return "channel"
	case *types.Signature:
		return "func"
	default:
		return fmt.Sprintf("%T", t)
	}
}

func typeReferenceFromSyntax(expr ast.Expr) TypeReference {
	// Fallback method when type information is not available
	switch t := expr.(type) {
	case *ast.Ident:
		return TypeReference{
			Name: t.Name,
			Kind: "unknown", // Without type checking, we don't know the kind
		}
	case *ast.SelectorExpr:
		if x, ok := t.X.(*ast.Ident); ok {
			return TypeReference{
				Name:           t.Sel.Name,
				PackageName:    x.Name,
				FullyQualified: fmt.Sprintf("%s.%s", x.Name, t.Sel.Name),
				Kind:           "unknown",
			}
		}
	case *ast.StarExpr:
		inner := typeReferenceFromSyntax(t.X)
		return TypeReference{
			Name:        "*" + inner.Name,
			Kind:        "pointer",
			IsPointer:   true,
			ElementType: &inner,
		}
	case *ast.ArrayType:
		if t.Len == nil {
			// Slice
			inner := typeReferenceFromSyntax(t.Elt)
			return TypeReference{
				Name:        "[]" + inner.Name,
				Kind:        "slice",
				IsSlice:     true,
				ElementType: &inner,
			}
		} else {
			// Array
			inner := typeReferenceFromSyntax(t.Elt)
			return TypeReference{
				Name:        "[array]" + inner.Name,
				Kind:        "array",
				ElementType: &inner,
			}
		}
	case *ast.MapType:
		key := typeReferenceFromSyntax(t.Key)
		value := typeReferenceFromSyntax(t.Value)
		return TypeReference{
			Name:        fmt.Sprintf("map[%s]%s", key.Name, value.Name),
			Kind:        "map",
			IsMap:       true,
			KeyType:     &key,
			ElementType: &value,
		}
	case *ast.InterfaceType:
		return TypeReference{
			Name: "interface{}",
			Kind: "interface",
		}
	case *ast.StructType:
		return TypeReference{
			Name: "struct{}",
			Kind: "struct",
		}
	case *ast.FuncType:
		return TypeReference{
			Name: "func",
			Kind: "func",
		}
	case *ast.ChanType:
		inner := typeReferenceFromSyntax(t.Value)
		return TypeReference{
			Name:        "chan " + inner.Name,
			Kind:        "channel",
			ElementType: &inner,
		}
	case *ast.Ellipsis:
		// Variadic parameter
		inner := typeReferenceFromSyntax(t.Elt)
		return TypeReference{
			Name:        "..." + inner.Name,
			Kind:        inner.Kind,
			ElementType: &inner,
		}
	default:
		return TypeReference{
			Name: fmt.Sprintf("%T", expr),
			Kind: "unknown",
		}
	}

	return TypeReference{
		Name: "unknown",
		Kind: "unknown",
	}
}

func isHigherOrderFunction(params []Parameter, returnTypes []TypeReference) bool {
	// Check if any parameter is a function type
	for _, param := range params {
		if param.Type.Kind == "func" {
			return true
		}
	}

	// Check if any return type is a function
	for _, rt := range returnTypes {
		if rt.Kind == "func" {
			return true
		}
	}

	return false
}
